@dataclass(frozen=True)
class Policy:
    any_of: tuple = ()
    all_of: tuple = ()
    global_permission: str | None = None

    def allows(self, permissions, globals_):
        has = lambda code: "*" in permissions or code in permissions
        return ((not self.any_of or any(has(code) for code in self.any_of))
                and all(has(code) for code in self.all_of)
                and (not self.global_permission or "*" in globals_ or self.global_permission in globals_))


@dataclass(frozen=True)
class KnowledgeChunk:
    id: str
    module: str
    title: str
    text: str
    source: str
    section: str
    revision: str
    href: str | None
    policy: Policy


