# Binds conversation history to exact reviewed content and policy, not a date label.
VERSION = hashlib.sha256(repr(CHUNKS).encode()).hexdigest()


def permitted_chunks(permissions, global_permissions):
    return [row for row in CHUNKS if row.policy.allows(permissions, global_permissions)]
